  bold=new CheckBox{Content="Bold",IsChecked=draft.Bold,Margin=new Thickness(0,12,0,0)};left.Children.Add(bold);
  Label(left,"Countdown font size");countdownSize=new Slider{Minimum=14,Maximum=60,Value=draft.CountdownSize,TickFrequency=1,IsSnapToTickEnabled=true};left.Children.Add(countdownSize);var countValue=new TextBlock();left.Children.Add(countValue);
  Label(left,"Class and end-time font size");labelSize=new Slider{Minimum=8,Maximum=22,Value=draft.LabelSize,TickFrequency=1,IsSnapToTickEnabled=true};left.Children.Add(labelSize);var labelValue=new TextBlock();left.Children.Add(labelValue);
  var dial=new Dial{Theme=draft,Time="04:32",Caption="计算机科学 CS",Footer="Ends 10:04",Fraction=0.65};var box=new Viewbox{Child=dial,HorizontalAlignment=HorizontalAlignment.Center};right.Children.Add(new Border{Child=box,Background=Dial.Brush("#DCE5EF"),CornerRadius=new CornerRadius(12),Padding=new Thickness(10),Height=160});
  Action update=delegate{};textColour=ColourRow(right,"Text colour",draft.TextColour,delegate{update();});fillColour=ColourRow(right,"Fill colour (round / bar)",draft.FillColour,delegate{update();});borderColour=ColourRow(right,"Border / progress / numeric outline",draft.BorderColour,delegate{update();});warningColour=ColourRow(right,"Warning colour (countdown / progress)",draft.WarningColour,delegate{update();});var previewWarning=new CheckBox{Content="Preview warning colour",Margin=new Thickness(0,12,0,0)};right.Children.Add(previewWarning);right.Children.Add(new TextBlock{Text="Uses lesson warning minutes when greater than 0.",TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(0,8,0,0)});previewWarning.Checked+=delegate{update();};previewWarning.Unchecked+=delegate{update();};
  update=delegate{draft.FontName=(string)font.SelectedItem;draft.Bold=bold.IsChecked==true;draft.CountdownSize=countdownSize.Value;draft.LabelSize=labelSize.Value;countValue.Text=countdownSize.Value.ToString("0")+" px";labelValue.Text=labelSize.Value.ToString("0")+" px";if(ValidColour(textColour.Text))draft.TextColour=textColour.Text;if(ValidColour(fillColour.Text))draft.FillColour=fillColour.Text;if(ValidColour(borderColour.Text))draft.BorderColour=borderColour.Text;if(ValidColour(warningColour.Text))draft.WarningColour=warningColour.Text;dial.IsWarning=previewWarning.IsChecked==true;dial.Mode=(string)view.SelectedItem;var size=Dial.DesignSize(dial.Mode);dial.Width=size.Width;dial.Height=size.Height;double fit=Math.Min(scale.Value,Math.Min(310/size.Width,140/size.Height));box.Width=size.Width*fit;box.Height=size.Height*fit;dial.InvalidateVisual();};
  view.SelectionChanged+=delegate{update();};font.SelectionChanged+=delegate{update();};bold.Checked+=delegate{update();};bold.Unchecked+=delegate{update();};scale.ValueChanged+=delegate{update();};countdownSize.ValueChanged+=delegate{update();};labelSize.ValueChanged+=delegate{update();};update();
