 UIElement Timetable(){var p=new DockPanel{Margin=new Thickness(18)};
  var top=new StackPanel();top.Children.Add(Text("Your weekly timetable",21));top.Children.Add(Text("Double-click cells to edit. Times use HH:mm. Warning = minutes before the end; 0 turns it off. Adjacent lessons are allowed; overlapping lessons are not.",12));
  var tools=new WrapPanel{Margin=new Thickness(0,0,0,12)};tools.Children.Add(Button("Add lesson",delegate{if(!Commit())return;var l=new Lesson();rows.Add(l);table.SelectedItem=l;table.ScrollIntoView(l);}));
  tools.Children.Add(Button("Duplicate",delegate{if(!Commit())return;var l=table.SelectedItem as Lesson;if(l!=null){var copy=new Lesson{Day=l.Day,Name=l.Name+" (copy)",Start=l.Start,End=l.End,StartAlert=l.StartAlert,EndAlert=l.EndAlert,WarningMinutes=l.WarningMinutes};rows.Add(copy);table.SelectedItem=copy;table.ScrollIntoView(copy);}}));
  tools.Children.Add(Button("Remove selected",delegate{if(!Commit())return;foreach(var l in table.SelectedItems.Cast<Lesson>().ToArray())rows.Remove(l);}));top.Children.Add(tools);
  var csvTools=new WrapPanel{Margin=new Thickness(0,0,0,10)};importMode=new ComboBox{ItemsSource=new[]{"Replace timetable","Append to timetable"},SelectedIndex=0,Width=165,Margin=new Thickness(0,0,8,0)};csvTools.Children.Add(importMode);csvTools.Children.Add(Button("Import CSV…",ImportCsv));csvTools.Children.Add(Button("Save CSV template…",delegate{var dialog=new SaveFileDialog{Title="Save timetable template",FileName="ClassAlerts-schedule-template.csv",Filter="CSV UTF-8 (*.csv)|*.csv"};if(dialog.ShowDialog(this)==true)Try(delegate{ScheduleCsv.WriteTemplate(dialog.FileName);feedback.Text="Template saved. In Excel, choose CSV UTF-8 when saving your edits.";});}));top.Children.Add(csvTools);top.Children.Add(Text("CSV imports update this draft only. Review the rows, then Save & close; Cancel keeps your existing schedule.",12));DockPanel.SetDock(top,Dock.Top);p.Children.Add(top);
  table=new DataGrid{ItemsSource=rows,AutoGenerateColumns=false,CanUserAddRows=false,CanUserDeleteRows=false,SelectionMode=DataGridSelectionMode.Extended,HeadersVisibility=DataGridHeadersVisibility.Column,RowHeaderWidth=0,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal,HorizontalGridLinesBrush=Dial.Brush("#E5EBF2"),AlternatingRowBackground=Dial.Brush("#F5F8FB"),RowHeight=39,ColumnHeaderHeight=35,BorderThickness=new Thickness(0)};
  table.Columns.Add(new DataGridComboBoxColumn{Header="Day",ItemsSource=Schedule.Days,SelectedItemBinding=new Binding("Day"),SortMemberPath="Day",Width=110});
  table.Columns.Add(new DataGridTextColumn{Header="Class / lesson",Binding=new Binding("Name"),Width=new DataGridLength(1,DataGridLengthUnitType.Star),MinWidth=170});
  table.Columns.Add(new DataGridTextColumn{Header="Start",Binding=new Binding("Start"),Width=75});table.Columns.Add(new DataGridTextColumn{Header="End",Binding=new Binding("End"),Width=75});
  table.Columns.Add(new DataGridTextColumn{Header="Warning",Binding=new Binding("WarningMinutes"){ValidatesOnExceptions=true},Width=75});
  table.Columns.Add(new DataGridCheckBoxColumn{Header="Start ♪",Binding=new Binding("StartAlert"),Width=65});table.Columns.Add(new DataGridCheckBoxColumn{Header="End ♪",Binding=new Binding("EndAlert"),Width=65});table.Sorting+=HandleSorting;SortByDay(false);table.RowEditEnding+=delegate{Dispatcher.BeginInvoke(new Action(delegate{var current=(ListCollectionView)CollectionViewSource.GetDefaultView(rows);if(current.CustomSort!=null&&!current.IsEditingItem&&!current.IsAddingNew)current.Refresh();}));};p.Children.Add(table);return p;
 }
 internal void SortByDay(bool descending){var list=(ListCollectionView)CollectionViewSource.GetDefaultView(rows);list.CustomSort=new DayLessonComparer(descending);foreach(var column in table.Columns)column.SortDirection=null;table.Columns[0].SortDirection=descending?ListSortDirection.Descending:ListSortDirection.Ascending;table.Columns[2].SortDirection=ListSortDirection.Ascending;}
 internal void HandleSorting(object sender,DataGridSortingEventArgs e){if(!Commit()){e.Handled=true;return;}if(e.Column==table.Columns[0]){e.Handled=true;SortByDay(e.Column.SortDirection==ListSortDirection.Ascending);}else{((ListCollectionView)CollectionViewSource.GetDefaultView(rows)).CustomSort=null;}}
 bool Commit(){if(table==null)return true;if(!table.CommitEdit(DataGridEditingUnit.Cell,true)||!table.CommitEdit(DataGridEditingUnit.Row,true)){feedback.Text="Please finish editing the highlighted cell. Warning minutes must be a whole number.";return false;}return true;}
 void ImportCsv(){if(!Commit())return;var dialog=new OpenFileDialog{Title="Import timetable CSV",Filter="CSV UTF-8 (*.csv)|*.csv",CheckFileExists=true};if(dialog.ShowDialog(this)!=true)return;Try(delegate{var imported=ScheduleCsv.Read(dialog.FileName);var candidate=importMode.SelectedIndex==1?rows.Concat(imported).ToList():imported;Schedule.Validate(candidate);rows.Clear();foreach(var lesson in candidate)rows.Add(lesson);feedback.Text=imported.Count+" lessons imported into the draft. Review and Save & close to apply.";});}
 static Brush Contrast(string value){var c=(Color)ColorConverter.ConvertFromString(value);return c.R*0.299+c.G*0.587+c.B*0.114<140?Brushes.White:Dial.Brush("#193B50");}
 static bool ValidColour(string value){return System.Text.RegularExpressions.Regex.IsMatch(value??"",@"^#[0-9a-fA-F]{6}$");}
 TextBox ColourRow(Panel panel,string label,string initial,Action changed){Label(panel,label);var row=new DockPanel();var value=new TextBox{Text=initial,MaxLength=7,Width=110,HorizontalAlignment=HorizontalAlignment.Left};var picker=Button("Choose…",delegate{using(var dialog=new Forms.ColorDialog{FullOpen=true}){if(ValidColour(value.Text))dialog.Color=System.Drawing.ColorTranslator.FromHtml(value.Text);if(dialog.ShowDialog()==Forms.DialogResult.OK)value.Text=String.Format("#{0:X2}{1:X2}{2:X2}",dialog.Color.R,dialog.Color.G,dialog.Color.B);}});picker.Background=Dial.Brush(initial);picker.Foreground=Contrast(initial);DockPanel.SetDock(picker,Dock.Right);row.Children.Add(picker);row.Children.Add(value);panel.Children.Add(row);value.TextChanged+=delegate{if(ValidColour(value.Text)){picker.Background=Dial.Brush(value.Text);picker.Foreground=Contrast(value.Text);}changed();};return value;}
 ComboBox SoundRow(Panel p,string label,string selected){Label(p,label);var row=new DockPanel{Margin=new Thickness(0,0,0,10)};var combo=new ComboBox{ItemsSource=controller.Sounds.Choices(),DisplayMemberPath="Label",SelectedValuePath="Id",SelectedValue=selected};var preview=Button("Preview",delegate{Try(delegate{controller.Sounds.Play((string)combo.SelectedValue);});});DockPanel.SetDock(preview,Dock.Right);row.Children.Add(preview);var add=Button("Import WAV…",delegate{Import(combo);});DockPanel.SetDock(add,Dock.Right);row.Children.Add(add);row.Children.Add(combo);p.Children.Add(row);return combo;}
 UIElement SoundPage(){var p=Page();p.Children.Add(Text("A sound for every transition",21));p.Children.Add(Text("Choose a built-in sound, silence, or import your own. The selection applies to all lessons; enable individual alerts in the timetable.",13));startSound=SoundRow(p,"Lesson starts",draft.StartSound);warningSound=SoundRow(p,"Before the lesson ends",draft.WarningSound);endSound=SoundRow(p,"Lesson ends / manual timer finishes",draft.EndSound);p.Children.Add(Button("Stop preview",delegate{controller.Sounds.Stop();}));p.Children.Add(new TextBlock{Text="Custom audio: uncompressed PCM WAV, mono/stereo, 8-bit or 16-bit, up to 20 MB. Imported sounds are copied into the app’s local sound library; no upload to an online service.",TextWrapping=TextWrapping.Wrap,Foreground=Dial.Brush("#64778D"),Margin=new Thickness(0,20,0,0)});return new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
 void Import(ComboBox target){var pick=new OpenFileDialog{Title="Choose a custom alert sound",Filter="PCM WAV audio (*.wav)|*.wav",CheckFileExists=true};if(pick.ShowDialog(this)!=true)return;Try(delegate{string id=controller.Sounds.Import(pick.FileName);foreach(var c in new[]{startSound,warningSound,endSound}){var old=c.SelectedValue;c.ItemsSource=controller.Sounds.Choices();c.SelectedValue=old;}target.SelectedValue=id;feedback.Text="Sound imported. Save changes to use it for this alert.";});}
 UIElement About(){var p=Page();Label(p,"Windows startup");startWithWindows=new CheckBox{Content="Start Class Alerts when I sign in to Windows",IsChecked=Startup.Enabled,Margin=new Thickness(0,0,0,18)};p.Children.Add(startWithWindows);p.Children.Add(Text("About Class Alerts",24));p.Children.Add(Text("A classroom countdown that stays in view.",14));Label(p,"Created by");p.Children.Add(Text("Francisco Javier Vertedor Postigo",20));Label(p,"License");p.Children.Add(Text("Creative Commons Attribution–NonCommercial 4.0 International\nCC BY-NC 4.0",16));p.Children.Add(Text("Attribution: Francisco Javier Vertedor Postigo · Class Alerts",13));var link=new System.Windows.Documents.Hyperlink(new System.Windows.Documents.Run("Read the CC BY-NC 4.0 license")){NavigateUri=new Uri("https://creativecommons.org/licenses/by-nc/4.0/")};link.RequestNavigate+=delegate(object sender,System.Windows.Navigation.RequestNavigateEventArgs e){Try(delegate{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(e.Uri.AbsoluteUri){UseShellExecute=true});});e.Handled=true;};var text=new TextBlock{Margin=new Thickness(0,6,0,16)};text.Inlines.Add(link);p.Children.Add(text);p.Children.Add(Button("View full license text",delegate{Try(delegate{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"LICENSE.txt")){UseShellExecute=true});});}));return new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
 UIElement ManualPage(){var p=Page();p.Children.Add(Text("Try it now",21));p.Children.Add(Text("Manual timers run independently of the timetable. Return to timetable mode whenever you are ready. Sound selections take effect after saving.",13));Label(p,"Class or activity name");title=new TextBox{Text="Manual timer",MaxLength=120};p.Children.Add(title);Label(p,"Duration in minutes");minutes=new TextBox{Text="5",Width=140,HorizontalAlignment=HorizontalAlignment.Left};p.Children.Add(minutes);
  var actions=new WrapPanel{Margin=new Thickness(0,20,0,20)};actions.Children.Add(Button("Start timer",delegate{Try(delegate{double n;if(!Double.TryParse(minutes.Text,out n)||Double.IsNaN(n)||Double.IsInfinity(n)||n<=0||n>1440)throw new Exception("Enter a duration greater than 0 and no more than 1440 minutes.");controller.StartManual(n,String.IsNullOrWhiteSpace(title.Text)?"Manual timer":title.Text.Trim());feedback.Text="Timer started. Close settings when you are ready to present.";});}));actions.Children.Add(Button("Pause / resume",delegate{feedback.Text=controller.Pause();}));p.Children.Add(actions);
  p.Children.Add(Button("Use lesson timetable",delegate{controller.UseSchedule();feedback.Text="Timetable mode is active.";}));return p;
 }
 void Try(Action a){try{a();}catch(Exception ex){feedback.Text=ex.Message;}}
 void Save(){if(!Commit())return;Try(delegate{draft.WarningColour=warningColour.Text;draft.TextColour=textColour.Text;draft.FillColour=fillColour.Text;draft.BorderColour=borderColour.Text;draft.View=(string)view.SelectedItem;draft.Scale=scale.Value;draft.Lessons=rows.ToList();draft.StartSound=(string)startSound.SelectedValue;draft.WarningSound=(string)warningSound.SelectedValue;draft.EndSound=(string)endSound.SelectedValue;controller.Apply(draft);Startup.SetEnabled(startWithWindows.IsChecked==true);Close();});}
